--sql_divide_splitter--

CACHE TABLE srp_cube_${grass_region_without_quote} AS
SELECT
    user_id
    ,if(sort_type IS NOT NULL, cast(sort_type AS STRING), '__ALL__') AS sort_type
    ,if(is_ads IS NOT NULL, cast(is_ads AS STRING), '__ALL__') AS is_ads
    ,if(target_type IS NOT NULL, target_type, '__ALL__') AS target_type

    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,power(sum(order_cnt), 2) AS squared_user_order_sum
    ,case when sum(order_cnt) > 0 then sum(gmv)/sum(order_cnt) else 0 end as abs
FROM
    dws_search_srp_${grass_region_without_quote}
GROUP BY GROUPING SETS
(
    (user_id, sort_type, is_ads, target_type), (user_id, is_ads, target_type)
    ,(user_id, sort_type, target_type), (user_id, target_type)
    ,(user_id, sort_type, is_ads), (user_id, is_ads)
    ,(user_id, sort_type), (user_id)
)
UNION ALL
SELECT
    user_id
    ,if(sort_type IS NOT NULL, cast(sort_type AS STRING), '__ALL__') AS sort_type
    ,if(is_ads IS NOT NULL, cast(is_ads AS STRING), '__ALL__') AS is_ads
    ,CASE
        WHEN page_type IN ('global_search', 'search_in_pdp', 'search_prefill') AND target_type IN ('item', 'video', 'livestream') THEN 'item+video+live' 
        ELSE 'buy_together_card'
    END AS target_type
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,power(sum(order_cnt), 2) AS squared_user_order_sum
    ,case when sum(order_cnt) > 0 then sum(gmv)/sum(order_cnt) else 0 end as abs
FROM
    dws_search_srp_${grass_region_without_quote}
WHERE
    (page_type IN ('global_search', 'search_in_pdp', 'search_prefill') 
        AND target_type IN ('item', 'video', 'livestream')
    )
    OR (
       imp_cnt >0 AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill') 
       AND target_type = 'buy_together'
    )OR (
        click_cnt >0 AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill') 
        AND target_type IN ('buy_together-title_bar','buy_together-item','buy_together-add_to_cart_button')
    )OR (
        order_cnt >0 AND page_type IN ('global_search', 'search_in_pdp', 'search_prefill')
        AND target_type IN ('buy_together-item','buy_together-add_to_cart_button')
    )OR (
        order_cnt >0 AND page_type IN ('buy_together')
        AND target_type IN ('buy_together_panel-item','buy_together_panel-add_to_cart_button')
    )
GROUP BY 
1,4
,cube(sort_type, is_ads)
UNION ALL 
SELECT
    user_id
    ,if(sort_type IS NOT NULL, cast(sort_type AS STRING), '__ALL__') AS sort_type
    ,if(is_ads IS NOT NULL, cast(is_ads AS STRING), '__ALL__') AS is_ads
    ,target_type
    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,power(sum(order_cnt), 2) AS squared_user_order_sum
    ,case when sum(order_cnt) > 0 then sum(gmv)/sum(order_cnt) else 0 end as abs
FROM
    dws_search_srp_other_${grass_region_without_quote}
    lateral view explode(target_types) as target_type
GROUP BY 
1,4
,cube(sort_type, is_ads)
;

