CREATE TEMPORARY VIEW srp_exp_${grass_region_without_quote} AS
SELECT
/*+ BROADCASTJOIN(c) */
    exp_group_id
    ,sort_type
    ,b.is_ads
    ,target_type

    ,SUM(imp_cnt) AS imp_cnt
    ,SUM(click_cnt) AS click_cnt
    ,SUM(ppv_cnt) AS ppv_cnt
    ,SUM(cart_cnt) AS cart_cnt
    ,SUM(order_cnt) AS order_cnt
    ,SUM(gmv) AS gmv
    ,SUM(pc2_gmv) AS pc2_gmv
    ,SUM(squared_user_order_sum) AS squared_user_order_sum

    ,SUM(IF(imp_cnt > 0, 1, NULL)) AS imp_uu
    ,SUM(IF(click_cnt > 0, 1, NULL)) AS click_uu
    ,SUM(IF(ppv_cnt > 0, 1, NULL)) AS ppv_uu
    ,SUM(IF(cart_cnt > 0, 1, NULL)) AS cart_uu
    ,SUM(IF(order_cnt > 0, 1, NULL)) AS order_uu

    ,COUNT(DISTINCT IF(b.abs <= c.global_search_abs_995 AND imp_cnt >0, b.user_id, NULL)) AS imp_uu_995
    ,sum(IF(b.abs <= c.global_search_abs_995, imp_cnt, 0)) AS imp_cnt_995
    ,sum(IF(b.abs <= c.global_search_abs_995, order_cnt, 0)) AS order_cnt_995
    ,sum(IF(b.abs <= c.global_search_abs_995, gmv, 0)) AS gmv_995
    ,sum(IF(b.abs <= c.global_search_abs_995, pc2_gmv, 0)) AS pc2_gmv_995
FROM
    user_exp_mapping_${grass_region_without_quote} a 
    INNER JOIN srp_cube_${grass_region_without_quote} b
    ON a.user_id = b.user_id
    LEFT JOIN
    global_search_abs995_benchmark_${grass_region_without_quote} c
    ON
        b.is_ads = c.is_ads
GROUP BY 
    1,2,3,4;

