CREATE TEMPORARY VIEW search_volume_${grass_region_without_quote} AS
SELECT
    user_id
    ,count(DISTINCT
        CASE WHEN view_cnt > 0 THEN (device_id, keyword)
            ELSE NULL END
    ) AS search_volume
    ,count(DISTINCT
        CASE WHEN ppv_cnt > 0 AND target_type = 'item' AND page_section IS NULL THEN (device_id, keyword)
            ELSE NULL END
    ) AS search_success_result_volume
    ,count(DISTINCT
        CASE WHEN imp_cnt > 0 AND target_type = 'no_recall_general' THEN (device_id, keyword)
            ELSE NULL END
    ) AS search_non_result_volume
    ,count(DISTINCT
        CASE WHEN click_cnt > 0 AND target_type IN ('item','video','livestream') AND page_section IS NULL THEN (device_id, keyword)
            ELSE NULL END
    ) AS direct_search_success_volume
    ,count(DISTINCT
        CASE WHEN click_cnt > 0  AND (
            (target_type IN ('item','video','livestream', 'curated_search', 'live_stream_floating_preview') AND page_section IS NULL
            ) OR ((target_type LIKE 'shop%' OR target_type LIKE 'creator%') AND page_section IS NULL
            ) OR (page_section = 'creator')
            ) THEN (device_id, keyword) ELSE NULL END
    ) AS broad_search_success_volume
FROM
    srp_all_search_scene_${grass_region_without_quote}
WHERE
    page_type IN ('global_search', 'search_in_pdp', 'search_prefill') 
GROUP BY user_id;

--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_search_volumn_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,sum(search_volume) AS search_volume
    ,sum(search_success_result_volume) AS search_success_result_volume
    ,sum(search_non_result_volume) AS search_non_result_volume
    ,sum(direct_search_success_volume) AS direct_search_success_volume
    ,sum(broad_search_success_volume) AS broad_search_success_volume
FROM
    search_volume_${grass_region_without_quote} dws_search_volumn
    INNER JOIN user_exp_mapping_${grass_region_without_quote} user_exp
    ON user_exp.user_id = dws_search_volumn.user_id
GROUP BY exp_group_id;

