    AND grass_region = ${grass_region};

--sql_divide_splitter--
CREATE TEMPORARY VIEW dwm_sr_data_warehouse_platform_user_${grass_region_without_quote} AS
SELECT
    user_exp_mapping.user_id
    ,exp_group_id
    ,COALESCE(is_ads, 'false') AS is_ads
    ,order_cnt
    ,gmv
FROM
    active_user_experiment_group_mapping_${grass_region_without_quote} AS user_exp_mapping
    INNER JOIN platform_user_metric_${grass_region_without_quote} dwm_sr_data_warehouse_platform_user
        ON dwm_sr_data_warehouse_platform_user.user_id = user_exp_mapping.user_id;

--sql_divide_splitter--
CREATE TEMPORARY VIEW dwm_search_user_exp_platform_udf_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,IF(is_ads IS NOT NULL, CAST(is_ads AS STRING), '__ALL__') AS is_ads
    ,COUNT(DISTINCT user_id) AS platform_dau_udf
    ,SUM(order_cnt) AS platform_order_cnt_udf
    ,SUM(gmv) AS platform_gmv_udf
    ,count(DISTINCT IF(order_cnt > 0,user_id,NULL) ) AS platform_buyer_udf
FROM
    dwm_sr_data_warehouse_platform_user_${grass_region_without_quote}
GROUP BY GROUPING SETS
(
    (exp_group_id, is_ads), (exp_group_id)
);

--sql_divide_splitter--
-- ROI metric --

CREATE TEMPORARY VIEW ads_outlier_${grass_region_without_quote} AS 
SELECT    
    outlier_type
    ,max(if (percentile = 0.999, abs, 0)) as abs_999
FROM
    srdi_mart.ads_sr_data_warehouse_platform_feature_group_ads_outlier_1d
WHERE
    grass_region = ${grass_region}
    and local_date = ${local_date}
    and feature_group = 'Search'
GROUP BY 
    1;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwd_ads_${grass_region_without_quote} AS
SELECT 
    user_id
    ,IF(target_type IS NOT NULL, target_type, 'NA') AS target_type
    ,IF(sort_by IS NOT NULL, sort_by, 'NA') AS sort_by
    ,sum(ads_imp_cnt) as paidads_imp_cnt
    ,sum(if(location <= 19, ads_imp_cnt, 0)) as paidads_top20_imp_cnt
    ,sum(revenue_usd) as revenue_usd
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(ads_broad_order_cnt) as ads_broad_order_cnt
    ,sum(broad_gmv_usd) as broad_gmv_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
FROM 
    srdi_mart.dws_sr_data_warehouse_ads_request_benchmark_advv_1d a
WHERE 
    local_date = ${local_date}
    and grass_region = ${grass_region}
    and entrance = 1 --global search
    and ARRAY_CONTAINS(product_types, '__ALL__')
GROUP BY 
    1,2,3;

--sql_divide_splitter--

CREATE TEMPORARY VIEW ads_performance_${grass_region_without_quote} AS 
SELECT 
    user_id
    ,IF(target_type IS NOT NULL, target_type, '__ALL__') AS target_type
    ,IF(sort_by IS NOT NULL, sort_by, '__ALL__') AS sort_type
    ,sum(paidads_imp_cnt) as paidads_imp_cnt
    ,sum(paidads_top20_imp_cnt) as paidads_top20_imp_cnt
    ,sum(revenue_usd) as revenue_usd
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(ads_broad_order_cnt) as ads_broad_order_cnt
    ,sum(broad_gmv_usd) as broad_gmv_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,IF(sum(ads_order_cnt) = 0, 0, sum(ads_gmv_usd) / sum(ads_order_cnt)) as direct_abs
    ,IF(sum(ads_broad_order_cnt) = 0, 0, sum(broad_gmv_usd) / sum(ads_broad_order_cnt)) as broad_abs
FROM 
    dwd_ads_${grass_region_without_quote}
GROUP BY
    user_id
    ,CUBE(target_type, sort_by)
UNION ALL
SELECT 
    user_id
    ,'item+video+live' AS target_type
    ,IF(sort_by IS NOT NULL, sort_by, '__ALL__') AS sort_type
    ,sum(paidads_imp_cnt) as paidads_imp_cnt
    ,sum(paidads_top20_imp_cnt) as paidads_top20_imp_cnt
    ,sum(revenue_usd) as revenue_usd
    ,sum(ads_order_cnt) as ads_order_cnt
    ,sum(ads_broad_order_cnt) as ads_broad_order_cnt
    ,sum(broad_gmv_usd) as broad_gmv_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,IF(sum(ads_order_cnt) = 0, 0, sum(ads_gmv_usd) / sum(ads_order_cnt)) as direct_abs
    ,IF(sum(ads_broad_order_cnt) = 0, 0, sum(broad_gmv_usd) / sum(ads_broad_order_cnt)) as broad_abs
FROM 
    dwd_ads_${grass_region_without_quote}
WHERE
    target_type IN ('item', 'video', 'livestream')
GROUP BY
    user_id
    ,'item+video+live'
    ,CUBE(sort_by);

--sql_divide_splitter--

CREATE TEMPORARY VIEW exp_ads_performance_${grass_region_without_quote} AS 
SELECT
/*+ BROADCAST(b,c) */
    exp_group_id
    ,target_type
    ,sort_type
    ,sum(paidads_imp_cnt) as paidads_imp_cnt
    ,sum(paidads_top20_imp_cnt) as paidads_top20_imp_cnt
    ,sum(revenue_usd) as revenue_usd
    ,sum(ads_gmv_usd) as ads_gmv_usd
    ,sum(broad_gmv_usd) as broad_gmv_usd
    ,sum(if (b.abs_999 is not null, revenue_usd, 0)) as revenue_usd_999
    ,sum(if (b.abs_999 is not null, ads_gmv_usd, 0)) as ads_gmv_usd_999
    ,sum(if (c.abs_999 is not null, broad_gmv_usd, 0)) as broad_gmv_usd_999
FROM ads_performance_${grass_region_without_quote} a
    INNER JOIN user_exp_mapping_${grass_region_without_quote} user_exp
    ON a.user_id = user_exp.user_id
    LEFT JOIN (
        SELECT
            *
        FROM 
            ads_outlier_${grass_region_without_quote} 
        WHERE 
            outlier_type = 'direct_ads_abs'
    ) AS b 
    ON a.direct_abs <= b.abs_999
    LEFT JOIN (
        SELECT
            *
        FROM 
            ads_outlier_${grass_region_without_quote} 
        WHERE 
            outlier_type = 'broad_ads_abs'
    ) AS c ON a.broad_abs <= c.abs_999 
GROUP BY 
    1,2,3;

--sql_divide_splitter-- 

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_search_abtest_core_metrics_v2_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
/*+ BROADCASTJOIN(h) */
 /*+ REPARTITION(20) */
    scene_id
    ,scene_name
    ,layer_id
    ,layer_name
    ,experiment_id
    ,experiment_name
    ,a.exp_group_id
    ,exp_group_name
    ,'search_result' AS feature_type
    ,a.sort_type
    ,a.is_ads
    ,a.target_type

    ,exp_group_uu
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,if(a.is_ads = '__ALL__' and a.target_type = '__ALL__' ,view_cnt, NULL) AS view_cnt
    ,if(a.is_ads = '__ALL__' and a.target_type = '__ALL__' ,view_not_back_cnt, NULL) AS view_not_back_cnt
    ,cart_cnt
    ,order_cnt
    ,NULL AS algo_order_cnt
    ,squared_user_order_sum
    ,gmv
    ,pc2_gmv
    ,imp_uu
    ,click_uu
    ,ppv_uu
    ,if(a.is_ads = '__ALL__' and a.target_type = '__ALL__' ,view_uu, NULL) AS view_uu
    ,cart_uu
    ,order_uu

    ,search_scene_imp_cnt
    ,search_scene_top20_imp_cnt

    ,search_volume
    ,search_success_result_volume
    ,search_non_result_volume
    ,direct_search_success_volume
    ,broad_search_success_volume

    ,NULL AS platform_dau_udf
    ,NULL AS platform_order_cnt_udf
    ,NULL AS platform_gmv_udf
    ,NULL AS platform_buyer_udf

    ,paidads_imp_cnt
    ,paidads_top20_imp_cnt

    ,NULL AS imp_l3_cat_per_uu
    ,NULL AS clk_l3_cat_per_uu

    ,revenue_usd
    ,ads_gmv_usd
    ,broad_gmv_usd
    ,revenue_usd_999
    ,ads_gmv_usd_999
    ,broad_gmv_usd_999

    ,global_search_abs_995
    ,imp_uu_995
    ,imp_cnt_995
    ,order_cnt_995
    ,gmv_995
    ,pc2_gmv_995
FROM
    srp_exp_${grass_region_without_quote} a 
    LEFT JOIN exp_uu_${grass_region_without_quote} b 
        ON a.exp_group_id = b.exp_group_id
    LEFT JOIN search_scene_cube_${grass_region_without_quote} c 
        ON a.exp_group_id = c.exp_group_id
        AND a.is_ads <=> c.is_ads
        AND a.sort_type = c.sort_type
        AND a.target_type = c.target_type
    LEFT JOIN exp_search_volumn_${grass_region_without_quote} d 
        ON a.exp_group_id = d.exp_group_id
    LEFT JOIN exp_ads_performance_${grass_region_without_quote} e 
        ON a.exp_group_id = e.exp_group_id
        AND a.is_ads IN ('true', '__ALL__')
        AND a.sort_type = e.sort_type
        AND a.target_type = e.target_type
    LEFT JOIN dim_exp_${grass_region_without_quote} f
        ON a.exp_group_id = f.exp_group_id
    LEFT JOIN exp_search_view_${grass_region_without_quote} g 
        ON a.exp_group_id = g.exp_group_id
        AND a.sort_type = g.sort_type
    LEFT JOIN global_search_abs995_benchmark_${grass_region_without_quote} h
        ON a.is_ads = h.is_ads
UNION ALL
SELECT
 /*+ REPARTITION(20) */
    scene_id
    ,scene_name
    ,layer_id
    ,layer_name
    ,experiment_id
    ,experiment_name
    ,a.exp_group_id
    ,exp_group_name
    ,'search_guide' AS feature_type
    ,'__ALL__' AS sort_type
    ,'__ALL__' AS is_ads
    ,feature AS target_type

    ,exp_group_uu
    ,imp_cnt
    ,click_cnt
    ,NULL AS ppv_cnt
    ,view_cnt
    ,NULL AS view_not_back_cnt
    ,NULL AS cart_cnt
    ,NULL AS order_cnt
    ,NULL AS algo_order_cnt
    ,NULL AS squared_user_order_sum
    ,NULL AS gmv
    ,NULL AS pc2_gmv
    ,imp_uu
    ,click_uu
    ,NULL AS ppv_uu
    ,view_uu
    ,NULL AS cart_uu
    ,NULL AS order_uu

    ,NULL AS search_scene_imp_cnt
    ,NULL AS search_scene_top20_imp_cnt

    ,search_volume
    ,search_success_result_volume
    ,search_non_result_volume
    ,direct_search_success_volume
    ,broad_search_success_volume

    ,NULL AS platform_dau_udf
    ,NULL AS platform_order_cnt_udf
    ,NULL AS platform_gmv_udf
    ,NULL AS platform_buyer_udf

    ,NULL AS paidads_imp_cnt
    ,NULL AS paidads_top20_imp_cnt

    ,imp_l3_cat_per_uu
    ,clk_l3_cat_per_uu

    ,NULL AS revenue_usd
    ,NULL AS ads_gmv_usd
    ,NULL AS broad_gmv_usd
    ,NULL AS revenue_usd_999
    ,NULL AS ads_gmv_usd_999
    ,NULL AS broad_gmv_usd_999

    ,NULL AS global_search_abs_995
    ,NULL AS imp_uu_995
    ,NULL AS imp_cnt_995
    ,NULL AS order_cnt_995
    ,NULL AS gmv_995
    ,NULL AS pc2_gmv_995
FROM
    guide_exp_${grass_region_without_quote} a 
    LEFT JOIN exp_uu_${grass_region_without_quote} b 
    ON a.exp_group_id = b.exp_group_id
    LEFT JOIN exp_search_volumn_${grass_region_without_quote} c
    ON a.exp_group_id = c.exp_group_id
    LEFT JOIN dim_exp_${grass_region_without_quote} d
        ON a.exp_group_id = d.exp_group_id
UNION ALL
SELECT
 /*+ REPARTITION(20) */
    scene_id
    ,scene_name
    ,layer_id
    ,layer_name
    ,experiment_id
    ,experiment_name
    ,a.exp_group_id
    ,exp_group_name
    ,'platform_wide' AS feature_type
    ,'__ALL__' AS sort_type
    ,a.is_ads
    ,'__ALL__' AS target_type

    ,exp_group_uu
    ,omni_imp_cnt AS imp_cnt
    ,omni_click_cnt AS click_cnt
    ,ppv_cnt
    ,NULL AS view_cnt
    ,NULL AS view_not_back_cnt
    ,NULL AS cart_cnt
    ,order_cnt
    ,NULL AS algo_order_cnt
    ,NULL AS squared_user_order_sum
    ,gmv
    ,NULL AS pc2_gmv
    ,NULL AS imp_uu
    ,NULL AS click_uu
    ,NULL AS ppv_uu
    ,NULL AS view_uu
    ,NULL AS cart_uu
    ,NULL AS order_uu

    ,NULL AS search_scene_imp_cnt
    ,NULL AS search_scene_top20_imp_cnt

    ,NULL AS search_volume
    ,NULL AS search_success_result_volume
    ,NULL AS search_non_result_volume
    ,NULL AS direct_search_success_volume
    ,NULL AS broad_search_success_volume

    ,e.platform_dau_udf
    ,b.platform_order_cnt_udf
    ,b.platform_gmv_udf
    ,b.platform_buyer_udf

    ,NULL AS paidads_imp_cnt
    ,NULL AS paidads_top20_imp_cnt

    ,NULL AS imp_l3_cat_per_uu
    ,NULL AS clk_l3_cat_per_uu

    ,NULL AS revenue_usd
    ,NULL AS ads_gmv_usd
    ,NULL AS broad_gmv_usd
    ,NULL AS revenue_usd_999
    ,NULL AS ads_gmv_usd_999
    ,NULL AS broad_gmv_usd_999

    ,NULL AS global_search_abs_995
    ,NULL AS imp_uu_995
    ,NULL AS imp_cnt_995
    ,NULL AS order_cnt_995
    ,NULL AS gmv_995
    ,NULL AS pc2_gmv_995
FROM
    dws_platform_exp_metric_${grass_region_without_quote} a 
    LEFT JOIN dim_exp_${grass_region_without_quote} c
        ON a.exp_group_id = c.exp_group_id
    LEFT JOIN exp_uu_${grass_region_without_quote} d
    ON a.exp_group_id = d.exp_group_id
    LEFT JOIN dwm_search_user_exp_platform_udf_${grass_region_without_quote} b 
    ON a.exp_group_id = b.exp_group_id
        AND a.is_ads <=> b.is_ads
    LEFT JOIN dwm_search_user_exp_platform_udf_${grass_region_without_quote} e
    ON a.exp_group_id = e.exp_group_id
        AND e.is_ads = '__ALL__'
